import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static class Matrix {
        List<List<Long>> data;

        Matrix(int rows, int cols) {
            data = new ArrayList<>();
            for (int i = 0; i < rows; i++) {
                List<Long> row = new ArrayList<>();
                for (int j = 0; j < cols; j++) {
                    row.add(0L);
                }
                data.add(row);
            }
        }

        static Matrix multiply(Matrix A, Matrix B) {
            int aRows = A.data.size();
            int aCols = A.data.get(0).size();
            int bRows = B.data.size();
            int bCols = B.data.get(0).size();

            Matrix C = new Matrix(aRows, bCols);
            for (int i = 0; i < aRows; i++) {
                for (int k = 0; k < aCols; k++) {
                    long aVal = A.data.get(i).get(k);
                    for (int j = 0; j < bCols; j++) {
                        long bVal = B.data.get(k).get(j);
                        C.data.get(i).set(j, C.data.get(i).get(j) + aVal * bVal);
                    }
                }
            }
            return C;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long N = sc.nextLong();
        int K = sc.nextInt();

        int count = 0;
        long power = 1;
        while (power <= N) {
            power *= K;
            count++;
        }
        power /= K;

        int[] digits = new int[count];
        long tempN = N;
        long tempPower = power;
        for (int i = 0; i < count; i++) {
            digits[i] = (int) (tempN / tempPower);
            tempN %= tempPower;
            tempPower /= K;
        }

        Matrix[] R = new Matrix[40];
        for (int i = 0; i <= K; i++) {
            R[i] = new Matrix(K + 1, K + 1);
        }

        Matrix[][] D = new Matrix[101][40];
        for (int i = 0; i <= count; i++) {
            for (int j = 0; j < K; j++) {
                D[i][j] = new Matrix(K + 1, K + 1);
            }
        }

        // Initialize R[0] and R[1]
        R[0].data.get(K).set(K, 1L);
        R[1].data.get(K).set(K, 1L);
        for (int j = 0; j < K; j++) {
            R[0].data.get(j).set(j, 1L);
        }
        for (int j = 0; j < K; j++) {
            R[1].data.get((j + K - 1) % K).set(j, 1L);
        }
        for (int j = 2; j <= K; j++) {
            R[j] = Matrix.multiply(R[j - 1], R[1]);
        }

        // Initialize D[0][0]
        for (int j = 0; j < K; j++) {
            D[0][0].data.get(j).set(j, 1L);
            D[0][0].data.get(j).set(0, 1L);
        }

        int cnt = count;
        for (int i = 0; i <= cnt; i++) {
            for (int j = 1; j < K; j++) {
                Matrix temp1 = Matrix.multiply(R[K - j], D[i][0]);
                D[i][j] = Matrix.multiply(temp1, R[j]);
            }
            if (i + 1 <= cnt) {
                D[i + 1][0] = D[i][K - 1];
            }
        }

        Matrix ans = new Matrix(1, K + 1);
        ans.data.get(0).set(K, 1L);
        int md = 0;
        for (int i = 0; i < cnt; i++) {
            if (digits[i] != 0) {
                Matrix temp1 = Matrix.multiply(R[K - md], D[cnt - i - 1][digits[i] - 1]);
                ans = Matrix.multiply(temp1, R[md]);
            }
            md += digits[i];
            md %= K;
        }

        long res = 0;
        for (int i = 0; i <= K; i++) {
            res += ans.data.get(0).get(i);
        }
        System.out.println(res);
        sc.close();
    }
}
